import java.util.*;
import java.io.*;

public class Main {
    static String rollString(String s, long[][] ops) {
        // Write your solution here
        return s;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer("");
        List<String> tokens = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            st = new StringTokenizer(line);
            while (st.hasMoreTokens()) tokens.add(st.nextToken());
        }
        String s = tokens.get(0);
        int q = Integer.parseInt(tokens.get(1));
        long[][] ops = new long[q][3];
        for (int i = 0; i < q; i++) {
            for (int j = 0; j < 3; j++) ops[i][j] = Long.parseLong(tokens.get(2 + 3 * i + j));
        }
        System.out.println(rollString(s, ops));
    }
}
